   diff_id                             VARCHAR(1)       NOT NULL COLLATE 'en-ci' COMMENT 'Wenn eine_2 Lieferposition nicht vollständig beliefert werden kann, wird die Restmenge vom VZ nachgeliefert oder muss vom Markt neu bestellt werden. Diese Information wird auch als Nachlieferkennzeichen bezeichnet.',
   dat_lief_soll                       DATE             NOT NULL COMMENT 'Lieferdatum der Position',
   lief_typ_id                         VARCHAR(4)       NOT NULL COLLATE 'en-ci' COMMENT 'Klassifikation, mit der zwischen verschiedenen Arten der Lieferung unterschieden wird. Die Lieferart bestimmt, wie das System eine_2 Lieferung bearbeitet.',
   vertr_beleg_typ_id                  VARCHAR(4)       NOT NULL COLLATE 'en-ci' COMMENT 'Dieses Kennzeichen liefert die Information aus welchem Vorgang dieser Vertriebsbeleg generiert wurde, z. B. wurde der Lieferschein aufgrund eines Wareneingangs generiert.',
   wg_id                               INTEGER     NOT NULL COMMENT 'ID der Warengruppe',
   arthiertyp_id                       INTEGER     NOT NULL COMMENT 'Artikel_2 - Hierarchie - Typ - ID: kennzeichnet, ob es sich um eine_2 Hierarchie mit zwei- oder dreistelligen Warengruppen  handelt',
   kunde_id                            INTEGER     NOT NULL COMMENT 'Als Format wurde bewusst Integer gewählt - ist kein Versehen',
   wg_verkett_lief                     INTEGER     NOT NULL COMMENT 'Die Warengruppenverkettung gibt an, welche Artikel_2 gemeinsam auf eine_2 Palette gepackt werden.',
   lief_pal_typ_id                     VARCHAR(1)       NOT NULL COLLATE 'en-ci' COMMENT 'Der Palettentyp einer Lieferung kennzeichnet, ob es sich um eine_2 Ganzpalettenlieferung, Mischpalettenlieferung, Lieferung je Markt etc. handelt.',
