   werbeware_id                        VARCHAR(1)       NOT NULL COLLATE 'en-ci' COMMENT 'Aus besch_lief_2: Wenn die Bestellart eine_2 Werbebestellart ist. Wertevorrat: W = Werbung, N = Normalware, B = Beides W und N, S = Schnellschuss.',
   bestellart_id                       VARCHAR(4)       NOT NULL COLLATE 'en-ci' COMMENT 'Durch die Einkaufsbelegart kann man z.B. zwischen einer Bestellung, einer Anfrage und einem Lieferplan unterscheiden.',
   hu_status_id                        VARCHAR(4)       NOT NULL COLLATE 'en-ci' COMMENT 'Bewegungsstatus der Handling Unit_2',
   disponent_id                        VARCHAR(4)       NOT NULL COLLATE 'en-ci' COMMENT 'Disponent ID',
   anzahl_position                     INTEGER     COMMENT 'Anzahl der Positionen in der besch_lief_det_2',
   anzahl_position_charg_split         INTEGER     COMMENT 'Anzahl Lieferpositionen (mit Chargensplit)',
