   menge_lief_ist_pal                  NUMBER(29,3)     COMMENT 'Ist-Liefermenge in PAL',
   anzahl_stellplatz_ewm_ext_parent    NUMBER(29,2)      COMMENT 'Anz. Stellpatz (parent HU)',
   anzahl_stellplatz_ewm               NUMBER(29,2)      COMMENT 'Stellplatzfaktor',
   vk_netto_lief_ist                   NUMBER(29,4)     COMMENT 'Liefermenge Ist bewertet mit dem Verkaufspreis minus MehrWertSteuer. Redundant abgelegt zur Performancesteigerung',
   vk_netto_lief_soll                  NUMBER(29,4)     COMMENT 'Liefermenge soll bewertet mit dem Verkaufspreis minus MehrWertSteuer. Redundant abgelegt zur Performancesteigerung',
   transportsortiment_id               VARCHAR(2)       COLLATE 'en-ci' COMMENT 'Transportsortiment ID - concatenation of  Lagersortiment IDs that should be put on the same truck for transportation (for example 27 means Lagersortiment ID 2 and Lagersortiment ID 7 are transported together)',
   wg_verkett_fg                       INTEGER     NOT NULL COMMENT 'Flag. Zeigt an, ob eine_2 Warengruppenverkettung existiert. Aus dem Feld zzlvwgrvkhier_kz',
   ntvol_ladung                        NUMBER(29,3)     COMMENT 'Netto-Ladungsgvolumen der HU',
   ntvol_ladung_gedeckelt              NUMBER(29,3)     COMMENT 'Netto-Ladungsgvolumen der HU (gedeckelt)',
   menge_gefahrgut                     NUMBER(29,2)      COMMENT 'Menge Gefahrgut',
   wrg_id                              VARCHAR(3)       COMMENT 'Kurzbezeichnung der Währung, z.Bsp. CZK, EUR',
   brtvol_hu_oa                        NUMBER(29,3)     COMMENT 'Brutto-Ladungsvolumen der HU ohne das Volumen der aufgepackten Palette',
   ntvol_hu_oa                         NUMBER(29,3)     COMMENT 'Netto-Ladungsvolumen der HU ohne das Volumen der aufgepackten Palette',
   brtvol_hu_gedeckelt_oa              NUMBER(29,3)     COMMENT 'Brutto-Ladungsvolumen der HU ohne das Volumen der aufgepackten Palette (gedeckelt auf 2304 cdm)',
   ntvol_hu_gedeckelt_oa               NUMBER(29,3)     COMMENT '''Netto-Ladungsvolumen der HU ohne das Volumen der aufgepackten Palette (gedeckelt auf 2304 cdm)',
   brtgew_hu                           NUMBER(29,3)     COMMENT 'Brutto-Gewicht der HU',
   ntgew_hu                            NUMBER(29,3)     COMMENT 'Netto-Gewicht der HU',
   brtgew_hu_oa                        NUMBER(29,3)     COMMENT 'Brutto-Gewicht der HU ohne das Volumen der aufgepackten Palette',
   ntgew_hu_oa                         NUMBER(29,3)     COMMENT 'Netto-Gewicht der HU ohne das Volumen der aufgepackten Palette',
   menge_lief_ist_kolli_hu             NUMBER(29,3)     COMMENT 'Liefermenge in Kolli auf HU-Ebene',
   auslieferungsgruppe_id              VARCHAR(4)       COMMENT 'Auslieferungsgruppe aus ZLF_AUSLFEL_2',
   TD_UPDATE                           TIMESTAMP_LTZ(9) COMMENT 'Technical fields for synchronisation framework. Will be delted after last product migration',
   TD_INSERT                           TIMESTAMP_LTZ(9) COMMENT 'Technical fields for synchronisation framework. Will be delted after last product migration',
   CONSTRAINT PK_BESCH_LIEF_WA_WG_SUM PRIMARY KEY (mandant_id, wup_id, nb_id, lagernummer_id, versandstelle_id, lagerort_id, lagersortiment_id, diff_id, dat_lief_soll, lief_typ_id, vertr_beleg_typ_id, wg_id, arthiertyp_id, kunde_id, wg_verkett_lief, lief_pal_typ_id, lief_pal_typ_dwh_id, mandant_id_kunde, werbeware_id, bestellart_id, hu_status_id, disponent_id) NOT ENFORCED
)  COMMENT = 'Warenausgangs-Positionen auf Ebene Warengruppe';
